      ]
    },
    {
      "service": "worker",
      "kind": "runtime_fault",
      "mechanism": "Worker process is stuck in a bad state due to repeated disk quota errors from invoice-agent, causing messages to dead-letter and orphaned orders.",
      "supporting": ["E4", "E6", "E9", "E11", "E16", "E17", "E36"],
      "refuting": ["E35"],
      "explains": ["I2_no_orphaned_orders"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "worker"}}
      ]
    }
  ],
  "summary": "Sync-job disk quota exhaustion causes ledger errors, and worker runtime fault from invoice-agent issues causes orphaned orders."
}
